import{_ as t,o as e,c as a,a2 as n}from"./chunks/framework.Dxeykp0S.js";const _=JSON.parse('{"title":"Day 4 · 模块与包：Python 的 import 体系","description":"","frontmatter":{},"headers":[],"relativePath":"novice/04-modules.md","filePath":"novice/04-modules.md","lastUpdated":1787141678000}'),d={name:"novice/04-modules.md"};function i(r,o,l,s,c,p){return e(),a("div",null,[...o[0]||(o[0]=[n(`<h1 id="day-4-·-模块与包-python-的-import-体系" tabindex="-1">Day 4 · 模块与包：Python 的 import 体系 <a class="header-anchor" href="#day-4-·-模块与包-python-的-import-体系" aria-label="Permalink to &quot;Day 4 · 模块与包：Python 的 import 体系&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>Python 通过模块与包组织代码，其中包含 <code>__init__.py</code>、<code>__name__ == &quot;__main__&quot;</code>、相对导入与循环导入等关键概念。今天把项目结构这件事彻底搞清楚，并用 JS 模块系统作为可选对照。</p><h2 id="课程目标" tabindex="-1">课程目标 <a class="header-anchor" href="#课程目标" aria-label="Permalink to &quot;课程目标&quot;">​</a></h2><ul><li>理解模块、包、<code>__init__.py</code> 的角色</li><li>掌握绝对导入与相对导入，避开循环导入</li><li>理解 <code>if __name__ == &quot;__main__&quot;:</code> 的意义</li><li>能用 <code>uv</code> 组织一个规范的多模块项目</li></ul><h2 id="阅读学习" tabindex="-1">阅读学习 <a class="header-anchor" href="#阅读学习" aria-label="Permalink to &quot;阅读学习&quot;">​</a></h2><ul><li><a href="https://docs.python.org/zh-cn/3/tutorial/modules.html" target="_blank" rel="noreferrer">Python 官方教程第 6 章：模块</a></li><li><a href="https://docs.python.org/zh-cn/3/reference/import.html" target="_blank" rel="noreferrer">Python 官方：import 系统</a>（浏览即可）</li><li>对照速览：</li></ul><table tabindex="0"><thead><tr><th>JS</th><th>Python</th></tr></thead><tbody><tr><td><code>import { a } from &#39;./utils.js&#39;</code></td><td><code>from utils import a</code>（不打 <code>.py</code>）</td></tr><tr><td><code>import * as utils from &#39;./utils.js&#39;</code></td><td><code>import utils</code></td></tr><tr><td>默认导出</td><td>没有对应概念</td></tr><tr><td><code>index.js</code> 桶文件</td><td><code>__init__.py</code>（现代 Python 也常留空）</td></tr><tr><td><code>node_modules</code> 查找</td><td><code>sys.path</code> 按顺序查找</td></tr><tr><td><code>require.main === module</code></td><td><code>if __name__ == &quot;__main__&quot;:</code></td></tr><tr><td>顶层代码 import 时执行</td><td><strong>一样！</strong> Python 的 import 也有副作用</td></tr><tr><td>动态 <code>await import()</code></td><td><code>importlib.import_module()</code></td></tr></tbody></table><h2 id="任务作业" tabindex="-1">任务作业 <a class="header-anchor" href="#任务作业" aria-label="Permalink to &quot;任务作业&quot;">​</a></h2><ol><li><strong>搭建标准项目骨架</strong>：用 <code>uv init --package mytool</code> 创建一个 src-layout 项目，结构如下：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mytool/</span></span>
<span class="line"><span>├── pyproject.toml</span></span>
<span class="line"><span>└── src/mytool/</span></span>
<span class="line"><span>    ├── __init__.py</span></span>
<span class="line"><span>    ├── __main__.py      # 支持 python -m mytool</span></span>
<span class="line"><span>    ├── cli.py           # 命令行入口</span></span>
<span class="line"><span>    ├── core/</span></span>
<span class="line"><span>    │   ├── __init__.py</span></span>
<span class="line"><span>    │   └── engine.py</span></span>
<span class="line"><span>    └── utils/</span></span>
<span class="line"><span>        ├── __init__.py</span></span>
<span class="line"><span>        └── text.py</span></span></code></pre></div><p>要求：<code>cli.py</code> 能从 <code>core.engine</code> 和 <code>utils.text</code> 导入函数并组成一个可运行的小工具（功能自定，比如一个文本统计 CLI）。</p><ol start="2"><li><p><strong>感受 <code>__name__</code></strong>：在 <code>engine.py</code> 顶层写一句 <code>print(f&quot;engine imported, __name__={__name__}&quot;)</code>，然后分别用 <code>python -m mytool</code>、<code>python -c &quot;import mytool&quot;</code>、<code>python src/mytool/cli.py</code> 三种方式运行，观察打印差异，彻底理解模块被导入与被直接运行的区别。</p></li><li><p><strong>循环导入复现与修复</strong>：故意让 <code>a.py</code> import <code>b.py</code>、<code>b.py</code> 又 import <code>a.py</code>，观察 <code>ImportError</code>，然后用&quot;延迟导入（函数内 import）&quot;和&quot;重构提取公共模块&quot;两种方式修复。</p></li><li><p><strong>入口点（entry points）</strong>：在 <code>pyproject.toml</code> 中配置 <code>[project.scripts]</code>，让你的工具安装后可以直接在终端用 <code>mytool</code> 命令调用（对标 npm 的 <code>bin</code> 字段）。用 <code>uv tool install .</code> 或 <code>uv run mytool</code> 验证。</p></li></ol><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><ul><li><code>import a</code> 和 <code>from a import b</code> 在命名空间和副作用上有何区别？</li><li>为什么很多库的 <code>__init__.py</code> 是空的？它还可以承担什么职责？</li><li><code>python -m mymodule</code> 和 <code>python mymodule.py</code> 有什么区别？</li><li>Python 中为什么会发生循环导入？可以通过哪些方式解决？</li><li>相对导入 <code>from . import x</code> 在什么情况下会报 <code>attempted relative import</code> 错误？</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>记录今天的学习笔记。</p><h2 id="拓展阅读" tabindex="-1">拓展阅读 <a class="header-anchor" href="#拓展阅读" aria-label="Permalink to &quot;拓展阅读&quot;">​</a></h2><ul><li><a href="https://packaging.python.org/" target="_blank" rel="noreferrer">Python 打包用户指南</a></li><li><a href="https://packaging.python.org/en/latest/discussions/src-layout-vs-flat-layout/" target="_blank" rel="noreferrer">src layout vs flat layout</a></li></ul><h2 id="预告" tabindex="-1">预告 <a class="header-anchor" href="#预告" aria-label="Permalink to &quot;预告&quot;">​</a></h2><p>入门班通关！下一站<a href="/python-practices/basic/">基础班</a>，进入 Python 真正的深水区：面向对象、迭代器、生成器、装饰器。</p>`,21)])])}const m=t(d,[["render",i]]);export{_ as __pageData,m as default};
